  const prf = (tn, fp, fn, tp) => { const p = tp / (tp + fp), r = tp / (tp + fn); return { a: (tn + tp) / (tn + fp + fn + tp), p, r, f: 2 * p * r / (p + r) }; };
  const P1 = v => (v * 100).toFixed(1) + '%', R1 = v => +(v * 100).toFixed(1);
